steps.codeExample:
router = APIRouter(prefix="/emails")
def enviar_email(destino: str):
    print(f"Enviado para {destino}")

@router.post("/boas-vindas")
async def boas_vindas(email: str, bg: BackgroundTasks):
    bg.add_task(enviar_email, email)
    return {"status": "agendado"}

